void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float aspect = iResolution.x / iResolution.y;
    vec2 uv = fragCoord / iResolution.yy;
    uv.x -= aspect / 2.0 - 0.25; // Bring it to halfway point, then back a bit
    uv = uv * 2.0 - 1.0; // Turn 0..1 range into -1..1 range

    int recursion = 250;
    vec2 z = vec2(0.0);
    vec2 c = uv;

    int i;
    for (i = 0; i < recursion; i++) {
        z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
        if (z.x * z.x + z.y * z.y > 4.0) break;
    }

    float mask;
    if (i == recursion) {
        mask = 2.0;
    } else {
        mask = float(i) / 40.0;
    }

    vec3 col = vec3(0.6, 0.6, 0.9) * mask;

    fragColor = vec4(col, 1.0);
}
